// FILE: frontend/src/components/charts/CombinedChartMap.js
//
// --- VERSION 0.2.0-ALPHA ---
// - Map as background, chart overlay at 1/3 height.
// - Rotates map so log time flows left→right.
// - Anchors chart midline to median of most variable PID.
// - Adaptive sampling: max 200 points per PID or 200 log lines total.
//

import React, { useMemo, useRef } from 'react';
import TripMap from '../maps/TripMap';
import { Line } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend } from 'chart.js';
import zoomPlugin from 'chartjs-plugin-zoom';
import { getAverageHeading } from '../../utils/mapUtils';
import { sampleData } from '../../utils/samplingUtils';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, zoomPlugin);

export default function CombinedChartMap({
  log,                // { data, columns }
  selectedPIDs,       // array of PID names
  chartColors,        // array of colors for PIDs
  visibleRange,       // { min, max }
  setVisibleRange,    // function to update range
  mapColumns = ['latitude', 'longitude', 'operating_state']
}) {
  const chartRef = useRef(null);
  const windowSize = visibleRange.max - visibleRange.min;

  // Slice current window (fixed 30s runtime)
const windowData = useMemo(() => {
  if (!log?.data) return [];
  const startIndex = visibleRange.min;
  const endIndex = visibleRange.max;
  return log.data.slice(startIndex, endIndex + 1);
}, [log, visibleRange]);

  // Determine PID with greatest +/- variation in full log
  const anchorPID = useMemo(() => {
    if (!log?.data) return null;
    let maxVar = -Infinity;
    let pidName = null;
    selectedPIDs.forEach(pid => {
      if (pid === 'none') return;
      const values = log.data.map(row => row[pid]).filter(v => typeof v === 'number');
      if (!values.length) return;
      const range = Math.max(...values) - Math.min(...values);
      if (range > maxVar) {
        maxVar = range;
        pidName = pid;
      }
    });
    return pidName;
  }, [log, selectedPIDs]);

  // Compute median of anchor PID in current window
  const anchorMedian = useMemo(() => {
    if (!anchorPID || !windowData.length) return 0;
    const vals = windowData.map(row => row[anchorPID]).filter(v => typeof v === 'number').sort((a, b) => a - b);
    const mid = Math.floor(vals.length / 2);
    return vals.length % 2 ? vals[mid] : (vals[mid - 1] + vals[mid]) / 2;
  }, [anchorPID, windowData]);

  // Compute average heading for rotation
  const avgHeading = useMemo(() => {
    return getAverageHeading(windowData, mapColumns[0], mapColumns[1]);
  }, [windowData, mapColumns]);

  // Build chart datasets with adaptive sampling per PID
  const chartData = useMemo(() => {
    if (!log?.data) return { datasets: [] };
    const datasets = [];
    selectedPIDs.forEach((pid, idx) => {
      selectedPIDs.forEach((pid, idx) => {
        if (pid === 'none') return;
        datasets.push({
          label: pid,
          data: windowData.map(row => row[pid]),
          borderColor: chartColors[idx],
          pointRadius: 0,
          borderWidth: 2,
          tension: 0.4
        });
      });



      if (pid === 'none') return;
      const sampled = sampleData(windowData.map(row => ({
        x: row.timestamp,
        y: row[pid]
      })), 200); // cap at 200 points per PID
      datasets.push({
        label: pid,
        data: sampled.map(p => p.y),
        borderColor: chartColors[idx],
        pointRadius: 0,
        borderWidth: 2,
        tension: 0.4
      });
    });
    return {
      labels: windowData.map((_, i) => i),
      datasets
    };
  }, [windowData, selectedPIDs, chartColors]);

  const chartOptions = useMemo(() => ({
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      legend: { display: true, labels: { color: '#FFFFFF' } },
      zoom: { pan: { enabled: false }, zoom: { enabled: false } }
    },
    scales: {
      y: {
        type: 'logarithmic',
        min: Math.min(...windowData.map(r => Math.min(...selectedPIDs.map(pid => r[pid] || Infinity)))),
        max: Math.max(...windowData.map(r => Math.max(...selectedPIDs.map(pid => r[pid] || -Infinity)))),
        ticks: { color: '#9CA3AF' }
      },
      x: { ticks: { color: '#9CA3AF' } }
    }
  }), [windowData, selectedPIDs]);

  return (
    <div className="relative w-full aspect-square bg-gray-900 rounded-lg overflow-hidden">
      {/* Map background */}
      <div className="absolute inset-0">
        <TripMap
          primaryPath={windowData}
          columns={mapColumns}
          rotation={avgHeading}
          visibleRange={visibleRange}
          onBoundsRangeChange={() => {}}
          multiRoute={false}
        />
      </div>

      {/* Chart overlay */}
      <div className="absolute bottom-0 left-0 w-full h-1/3 bg-black/40 backdrop-blur-sm">
        <Line ref={chartRef} options={chartOptions} data={chartData} />
      </div>
    </div>
  );
}
